import java.util.Scanner;

public class Main {
    public static int process(int n, int mod) {
        if (n <= 3) {
            return 0;
        }
        int last_value = 17;
        int total_value = 17;
        int max_size = (n - 1) * (n - 2) / 2 + 1;
        int flag = 1;
        int[][] dp_table = new int[2][max_size + 1];
        // Initialize dp_table[0][0..3]
        for (int i = 0; i <= max_size; i++) {
            dp_table[0][i] = 0;
            dp_table[1][i] = 0;
        }
        dp_table[0][0] = 1;
        dp_table[0][1] = 2;
        dp_table[0][2] = 2;
        dp_table[0][3] = 1;

        for (int m = 4; m < n; m++) {
            int pair_count = m * (m - 1) / 2;
            total_value = (m + 1) * last_value;
            int cumulative = 0;
            for (int i = 0; i < m; i++) {
                cumulative += dp_table[flag ^ 1][i];
                cumulative %= mod;
                dp_table[flag][i] = cumulative;
            }
            for (int i = m; i <= pair_count / 2; i++) {
                cumulative += dp_table[flag ^ 1][i];
                cumulative -= dp_table[flag ^ 1][i - m];
                cumulative %= mod;
                if (cumulative < 0) {
                    cumulative += mod;
                }
                dp_table[flag][i] = cumulative;
            }
            for (int i = 0; i <= pair_count / 2; i++) {
                dp_table[flag][pair_count - i] = dp_table[flag][i];
            }
            int total_sum = 0;
            for (int i = 0; i < pair_count; i++) {
                int temp_sum = 0;
                int start_j = Math.max(1, -pair_count + i + m + 2);
                for (int j = start_j; j <= m; j++) {
                    int index = m + 2 - j + i;
                    if (index >= 0 && index <= max_size) {
                        temp_sum += j * dp_table[flag][index];
                    }
                }
                total_sum += dp_table[flag][i];
                total_sum %= mod;
                temp_sum %= mod;
                total_value += (long) temp_sum * total_sum;
                total_value %= mod;
            }
            last_value = total_value;
            flag ^= 1;
        }
        return total_value % mod;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int mod = scanner.nextInt();
        System.out.println(process(n, mod));
        scanner.close();
    }
}
